$GeneratedFiles = @{
    "supabase/migrations/20260812001520_sales_prospecting_crm_foundation_v1.sql" = ""
    "supabase/migrations/20260812002052_sales_prospecting_crm_hardening_v1.sql" = ""
    "lib/prospecting.ts" = ""
    "app/api/admin/prospecting/route.ts" = ""
    "components/admin/ProspectingCrmClient.tsx" = ""
    "app/admin/prospeccao/page.tsx" = "aW1wb3J0IFByb3NwZWN0aW5nQ3JtQ2xpZW50IGZyb20gJ0AvY29tcG9uZW50cy9hZG1pbi9Qcm9zcGVjdGluZ0NybUNsaWVudCcKCmV4cG9ydCBkZWZhdWx0IGZ1bmN0aW9uIFByb3NwZWNjYW9QYWdlKCkgewogIHJldHVybiA8UHJvc3BlY3RpbmdDcm1DbGllbnQgLz4KfQo="
}

$ExpectedSha = @{
    "supabase/migrations/20260812001520_sales_prospecting_crm_foundation_v1.sql" = "742072DCC9C8087BEF4CC17863CB21E31162088324A21A22620B92B3643C8CA8"
    "supabase/migrations/20260812002052_sales_prospecting_crm_hardening_v1.sql" = "F06FBD926121944E5D17E300E27CD33163CD0B1BA0D64291248E28670FDD7873"
    "lib/prospecting.ts" = "146CDB17E5F0F8A4813F778FB4DCCF6C3BBC3083C5E20B0134E98B8FD92945E6"
    "app/api/admin/prospecting/route.ts" = "CAD243988D9C35671A750944572F9B820D7AE17C833FD63B14438FD792B2F11C"
    "components/admin/ProspectingCrmClient.tsx" = "2B9696BA0789A72FFD170540E891CE0F5AC3279A7A084CCD6200851F06C7B3E8"
    "app/admin/prospeccao/page.tsx" = "B473D5A1926951E73927882CC1E87BA0B6E88B16B18FDA14F8325D80113339F1"
}

$Changed = New-Object System.Collections.Generic.List[string]
$Backups = @{}

function Step([string]$Text) {
    Write-Host ""
    Write-Host ("==> " + $Text) -ForegroundColor Cyan
}

function Ok([string]$Text) {
    Write-Host ("[OK] " + $Text) -ForegroundColor Green
}

function Warn([string]$Text) {
    Write-Host ("[AVISO] " + $Text) -ForegroundColor Yellow
}

function AssertCheck([bool]$Passed, [string]$Name) {
    if (-not $Passed) {
        throw ("Validacao falhou: " + $Name)
    }

    Ok $Name
}

function FullPath([string]$Relative) {
    return Join-Path $ProjectRoot ($Relative -replace "/", "\")
}

function NormalizeNewlines([string]$Value) {
    if ($null -eq $Value) { return "" }
    return $Value.Replace("`r`n", "`n").Replace("`r", "`n")
}

function Backup([string]$Relative) {
    $source = FullPath $Relative

    if (-not (Test-Path -LiteralPath $source -PathType Leaf)) {
        return
    }

    $destination = Join-Path $BackupRoot ($Relative -replace "/", "\")
    [IO.Directory]::CreateDirectory((Split-Path -Parent $destination)) | Out-Null
    Copy-Item -LiteralPath $source -Destination $destination -Force
    $Backups[$Relative] = $destination
}

function MarkChanged([string]$Relative) {
    if (-not $Changed.Contains($Relative)) {
        $Changed.Add($Relative)
    }
}

function WriteTextWithRetry([string]$Relative, [byte[]]$Bytes) {
    $path = FullPath $Relative
    $directory = Split-Path -Parent $path
    [IO.Directory]::CreateDirectory($directory) | Out-Null

    $temp = Join-Path $directory (
        "." +
        [IO.Path]::GetFileName($path) +
        ".orcaly-fase4-" +
        [Guid]::NewGuid().ToString("N") +
        ".tmp"
    )

    try {
        [IO.File]::WriteAllBytes($temp, $Bytes)

        $written = $false
        $lastError = $null

        for ($attempt = 1; $attempt -le 8; $attempt++) {
            try {
                if (Test-Path -LiteralPath $path -PathType Leaf) {
                    [IO.File]::Copy($temp, $path, $true)
                }
                else {
                    [IO.File]::Move($temp, $path)
                }

                $written = $true
                break
            }
            catch {
                $lastError = $_.Exception
                [GC]::Collect()
                [GC]::WaitForPendingFinalizers()
                Start-Sleep -Milliseconds (250 * $attempt)
            }
        }

        if (-not $written) {
            throw (
                "Windows manteve o arquivo bloqueado: " +
                $Relative +
                ". Feche npm run dev/VS Code e tente novamente. " +
                $(if ($lastError) { $lastError.Message } else { "" })
            )
        }
    }
    finally {
        Remove-Item -LiteralPath $temp -Force -ErrorAction SilentlyContinue
    }
}

function WriteGenerated([string]$Relative, [bool]$AllowReplace = $false) {
    $path = FullPath $Relative

    if (Test-Path -LiteralPath $path -PathType Leaf) {
        $actualSha = (Get-FileHash $path -Algorithm SHA256).Hash.ToUpperInvariant()

        if ($actualSha -eq $ExpectedSha[$Relative]) {
            Ok ($Relative + " ja corresponde a FASE 4.")
            return
        }

        if (-not $AllowReplace) {
            throw ($Relative + " ja existe com conteudo diferente.")
        }

        Backup $Relative
    }

    $bytes = [Convert]::FromBase64String($GeneratedFiles[$Relative])
    WriteTextWithRetry $Relative $bytes

    $writtenSha = (Get-FileHash (FullPath $Relative) -Algorithm SHA256).Hash.ToUpperInvariant()

    if ($writtenSha -ne $ExpectedSha[$Relative]) {
        throw ("SHA256 inesperado depois de gravar " + $Relative)
    }

    MarkChanged $Relative
    Ok ($Relative + " sincronizado.")
}

function Rollback {
    [array]$items = @($Changed)
    [Array]::Reverse($items)

    foreach ($relative in $items) {
        if ($Backups.ContainsKey($relative)) {
            Copy-Item -LiteralPath $Backups[$relative] -Destination (FullPath $relative) -Force
            Warn ("Restaurado: " + $relative)
        }
        else {
            Remove-Item -LiteralPath (FullPath $relative) -Force -ErrorAction SilentlyContinue
            Warn ("Removido: " + $relative)
        }
    }
}

try {
    Write-Host ""
    Write-Host "ORCALY - FASE 4 - CRM DE PROSPECCAO V3" -ForegroundColor Cyan
    Write-Host "Pipeline comercial + carteira propria + historico de contatos." -ForegroundColor DarkCyan

    if (-not (Test-Path -LiteralPath (FullPath "package.json") -PathType Leaf)) {
        throw "Repositorio Orcaly nao encontrado."
    }

    Set-Location $ProjectRoot

    $branch = ([string]((& git branch --show-current) | Select-Object -First 1)).Trim()

    if ($branch -ne $ExpectedBranch) {
        throw ("Branch atual: " + $branch + ". Esperada: " + $ExpectedBranch)
    }

    Step "Validando a FASE 2"

    $platformAdminPath = FullPath "lib/platform-admin.ts"

    if (-not (Test-Path -LiteralPath $platformAdminPath -PathType Leaf)) {
        throw "lib/platform-admin.ts nao encontrado."
    }

    $platformAdmin = NormalizeNewlines ([IO.File]::ReadAllText($platformAdminPath))

    foreach ($anchor in @(
        "'prospecting.access'",
        "'prospecting.view_own'",
        "'prospecting.view_all'",
        "'prospecting.create'",
        "'prospecting.edit_own'",
        "export function canPlatform",
        "export async function requirePlatformAdmin"
    )) {
        if (-not $platformAdmin.Contains($anchor)) {
            throw ("FASE 2 incompleta. Trecho ausente: " + $anchor)
        }

        Ok ("Permissao confirmada: " + $anchor)
    }

    Step "Validando pagina placeholder da Prospecção"

    $pageRelative = "app/admin/prospeccao/page.tsx"
    $pagePath = FullPath $pageRelative

    if (Test-Path -LiteralPath $pagePath -PathType Leaf) {
        $pageSha = (Get-FileHash $pagePath -Algorithm SHA256).Hash.ToUpperInvariant()

        if ($pageSha -ne $ExpectedSha[$pageRelative]) {
            $pageText = NormalizeNewlines ([IO.File]::ReadAllText($pagePath))

            if (
                -not $pageText.Contains("Orçaly Comercial") -or
                -not $pageText.Contains("O pipeline comercial será conectado aqui na FASE 4.")
            ) {
                throw (
                    $pageRelative +
                    " nao e o placeholder auditado da FASE 2 e possui conteudo diferente. Nao vou sobrescrever."
                )
            }

            Ok "Placeholder da FASE 2 reconhecido."
        }
        else {
            Ok "Pagina da FASE 4 ja esta sincronizada."
        }
    }
    else {
        throw (
            $pageRelative +
            " nao existe. A FASE 2 precisa estar aplicada antes da FASE 4."
        )
    }

    Step "Sincronizando migrations ja aplicadas no Supabase"

    WriteGenerated "supabase/migrations/20260812001520_sales_prospecting_crm_foundation_v1.sql"
    WriteGenerated "supabase/migrations/20260812002052_sales_prospecting_crm_hardening_v1.sql"

    Step "Criando backend e componentes da FASE 4"

    WriteGenerated "lib/prospecting.ts"
    WriteGenerated "app/api/admin/prospecting/route.ts"
    WriteGenerated "components/admin/ProspectingCrmClient.tsx"
    WriteGenerated $pageRelative $true

    Step "Validando isolamento e contrato"

    $apiText = NormalizeNewlines ([IO.File]::ReadAllText((FullPath "app/api/admin/prospecting/route.ts")))
    $clientText = NormalizeNewlines ([IO.File]::ReadAllText((FullPath "components/admin/ProspectingCrmClient.tsx")))
    $libText = NormalizeNewlines ([IO.File]::ReadAllText((FullPath "lib/prospecting.ts")))

    AssertCheck `
        ($apiText.Contains("'prospecting.access'")) `
        "API exige acesso comercial"

    AssertCheck `
        ($apiText.Contains("'prospecting.view_all'")) `
        "Owner possui visao global"

    AssertCheck `
        ($apiText.Contains("'prospecting.view_own'")) `
        "Prospector usa carteira propria"

    $hasReadWriteOwnershipFilters = (
        $apiText.Contains(".eq('assigned_to_admin_id', admin.id)") -and
        $apiText.Contains("query = query.eq(") -and
        $apiText.Contains("update = update.eq(") -and
        $apiText.Contains("'assigned_to_admin_id',") -and
        $apiText.Contains("session.admin.id")
    )

    AssertCheck `
        $hasReadWriteOwnershipFilters `
        "Filtros server-side por responsavel em leitura e escrita"

    $hasVisibleLeadOwnership = (
        $apiText.Contains("async function visibleLead(") -and
        $apiText.Contains("if (!canViewAll)") -and
        $apiText.Contains(".eq('assigned_to_admin_id', admin.id)")
    )

    AssertCheck `
        $hasVisibleLeadOwnership `
        "Detalhe individual respeita carteira propria"

    AssertCheck `
        ($apiText.Contains("create_or_claim_sales_prospect")) `
        "Criacao/claim atomico"

    AssertCheck `
        ($apiText.Contains("record_signup_lead_sales_followup")) `
        "Contato atomico"

    AssertCheck `
        ($apiText.Contains("change_signup_lead_sales_stage")) `
        "Mudanca de etapa atomica"

    AssertCheck `
        ($apiText.Contains("Essa etapa é automática")) `
        "Etapas de sistema bloqueadas na API"

    AssertCheck `
        ($libText.Contains("'convite_fundador'")) `
        "Etapa Founder preparada"

    AssertCheck `
        ($libText.Contains("'conta_ativada'")) `
        "Etapa conta ativada preparada"

    AssertCheck `
        ($clientText.Contains("O convite Founder real será conectado a esta etapa na FASE 5.")) `
        "UI nao finge que FASE 5 ja existe"

    Step "git diff --check"

    $phase4Files = @(
        "supabase/migrations/20260812001520_sales_prospecting_crm_foundation_v1.sql",
        "supabase/migrations/20260812002052_sales_prospecting_crm_hardening_v1.sql",
        "lib/prospecting.ts",
        "app/api/admin/prospecting/route.ts",
        "components/admin/ProspectingCrmClient.tsx",
        "app/admin/prospeccao/page.tsx"
    )

    & git --no-pager diff --check -- $phase4Files

    if ($LASTEXITCODE -ne 0) {
        throw "git diff --check falhou."
    }

    Ok "Whitespace validado."

    Step "ESLint direcionado"

    & npx.cmd eslint `
        "lib/prospecting.ts" `
        "app/api/admin/prospecting/route.ts" `
        "components/admin/ProspectingCrmClient.tsx" `
        "app/admin/prospeccao/page.tsx"

    if ($LASTEXITCODE -ne 0) {
        throw "ESLint direcionado da FASE 4 falhou."
    }

    Ok "ESLint direcionado passou."

    Step "Build completo"

    & npm.cmd run build

    if ($LASTEXITCODE -ne 0) {
        throw "Build final falhou."
    }

    Ok "Build final passou."

    Write-Host ""
    Write-Host "============================================================" -ForegroundColor Green
    Write-Host " FASE 4 APLICADA E VALIDADA LOCALMENTE" -ForegroundColor Green
    Write-Host "============================================================" -ForegroundColor Green
    Write-Host ""
    Write-Host "Implementado:"
    Write-Host " - Pipeline comercial separado de status de checkout"
    Write-Host " - Novo / Contatado / Interessado / Demonstracao"
    Write-Host " - Convite Founder / Conta ativada / Cliente / Perdido"
    Write-Host " - Prospector ve somente sua carteira"
    Write-Host " - Owner ve todos e redistribui responsaveis"
    Write-Host " - Cadastro manual de prospects"
    Write-Host " - Aproveitamento de leads inbound existentes"
    Write-Host " - Historico de WhatsApp / telefone / email / reuniao / nota"
    Write-Host " - Proxima acao e observacoes comerciais"
    Write-Host " - Etapas de sistema protegidas"
    Write-Host ""
    Write-Host "Nenhum commit, push ou deploy foi executado." -ForegroundColor Cyan
}
catch {
    Write-Host ""
    Write-Host ("[ERRO] " + $_.Exception.Message) -ForegroundColor Red

    if ($Changed.Count -gt 0) {
        Warn "Executando rollback dos arquivos alterados."
        Rollback
    }

    Write-Host ("Backup: " + $BackupRoot) -ForegroundColor Yellow
    exit 1
}
